import 'package:flutter/material.dart';\nimport '../../config/theme/app_theme.dart';\n\nclass TrekkingDashboardScreen extends StatefulWidget {\n  const TrekkingDashboardScreen({Key? key}) : super(key: key);\n\n  @override\n  State<TrekkingDashboardScreen> createState() => _TrekkingDashboardScreenState();\n}\n\nclass _TrekkingDashboardScreenState extends State<TrekkingDashboardScreen> {\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('Trekking Dashboard'),\n        backgroundColor: AppTheme.backgroundColor,\n      ),\n      backgroundColor: AppTheme.backgroundColor,\n      body: SingleChildScrollView(\n        padding: const EdgeInsets.all(16),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            _buildStatCard('Current Elevation', '2450 m', Icons.terrain),\n            const SizedBox(height: 12),\n            _buildStatCard('Distance Traveled', '8.5 km', Icons.route),\n            const SizedBox(height: 12),\n            _buildStatCard('Time Elapsed', '2h 30min', Icons.timer),\n            const SizedBox(height: 12),\n            _buildStatCard('Terrain Difficulty', 'Moderate', Icons.trending_up),\n            const SizedBox(height: 24),\n            Text(\n              'Nearby Resources',\n              style: Theme.of(context).textTheme.headlineLarge,\n            ),\n            const SizedBox(height: 12),\n            _buildResourceCard('Water Source', '1.2 km E', Icons.water),\n            _buildResourceCard('Campsite', '3.5 km NE', Icons.home),\n            _buildResourceCard('Danger Zone', '5.2 km S', Icons.warning),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildStatCard(String label, String value, IconData icon) {\n    return Card(\n      color: AppTheme.surfaceColor,\n      child: Padding(\n        padding: const EdgeInsets.all(16),\n        child: Row(\n          children: [\n            Icon(icon, color: AppTheme.primaryColor, size: 32),\n            const SizedBox(width: 16),\n            Column(\n              crossAxisAlignment: CrossAxisAlignment.start,\n              children: [\n                Text(\n                  label,\n                  style: const TextStyle(\n                    color: AppTheme.textTertiary,\n                    fontSize: 12,\n                  ),\n                ),\n                Text(\n                  value,\n                  style: const TextStyle(\n                    color: AppTheme.primaryColor,\n                    fontSize: 18,\n                    fontWeight: FontWeight.bold,\n                  ),\n                ),\n              ],\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildResourceCard(String name, String distance, IconData icon) {\n    return ListTile(\n      leading: Icon(icon, color: AppTheme.primaryColor),\n      title: Text(name, style: const TextStyle(color: AppTheme.textPrimary)),\n      subtitle: Text(distance, style: const TextStyle(color: AppTheme.textTertiary)),\n      trailing: const Icon(Icons.arrow_forward, color: AppTheme.primaryColor),\n    );\n  }\n}\n